export const calculateAP = (noteCount: number): string => {
  if (noteCount === 0) return '0.00';
  const baseScore = 60 / noteCount;
  let score = 0;

  if (noteCount <= 10) {
    score = noteCount * 1.0;
  } else if (noteCount <= 20) {
    score = 10 * 1.0 + (noteCount - 10) * 1.1;
  } else if (noteCount <= 30) {
    score = 10 * 1.0 + 10 * 1.1 + (noteCount - 20) * 1.2;
  } else if (noteCount <= 40) {
    score = 10 * 1.0 + 10 * 1.1 + 10 * 1.2 + (noteCount - 30) * 1.3;
  } else if (noteCount <= 50) {
    score = 10 * 1.0 + 10 * 1.1 + 10 * 1.2 + 10 * 1.3 + (noteCount - 40) * 1.4;
  } else {
    score = 10 * 1.0 + 10 * 1.1 + 10 * 1.2 + 10 * 1.3 + 10 * 1.4 + (noteCount - 50) * 1.5;
  }

  return (baseScore * score).toFixed(2);
};
