import { useData } from 'vike-react/useData';
import { useState } from 'react';
import { FaChevronDown } from 'react-icons/fa6';
import { useTranslation } from 'react-i18next';
import type { PageData } from './+data';
import { Combobox, createListCollection } from '~/components/ui/combobox';
import { Metadata } from '~/components/layout/Metadata';

import { Input } from '~/components/ui/input';
import { IconButton } from '~/components/ui/icon-button';
import { getAlbumArtPublicPath } from '~/utils/assets';
import { HStack, styled } from 'styled-system/jsx';
import { Card } from '~/components/ui/card';
import { Text } from '~/components/ui/text';
import { calculateAP } from '~/utils/calculator';

import { SITE_URL } from '~/utils/config';

export default function Page() {
  const { t } = useTranslation();
  const { songs }: PageData = useData();
  const [items, setItems] = useState(songs);
  const [selectedSong, setSelectedSong] = useState<PageData['songs'][0] | undefined>(undefined);

  const collection = createListCollection({
    items: items.map((item) => ({
      label: item.title,
      value: String(item.id)
    }))
  });

  return (
    <>
      <Metadata title={t('calculator_page.title')} canonical={`${SITE_URL}/calculator`} />
      <Combobox.Root
        collection={collection}
        onInputValueChange={({ inputValue }) =>
          setItems(
            songs.filter((item) => item.title.toLowerCase().includes(inputValue.toLowerCase()))
          )
        }
        onValueChange={({ value }) => {
          const song = songs.find((s) => String(s.id) === value[0]);
          setSelectedSong(song);
        }}
      >
        <Combobox.Label>{t('calculator_page.songs_label')}</Combobox.Label>
        <Combobox.Control>
          <Combobox.Input placeholder={t('calculator_page.select_song_placeholder')} asChild>
            <Input />
          </Combobox.Input>
          <Combobox.Trigger asChild>
            <IconButton variant="link" aria-label={t('calculator_page.open_aria_label')} size="xs">
              <FaChevronDown />
            </IconButton>
          </Combobox.Trigger>
        </Combobox.Control>
        <Combobox.Positioner>
          <Combobox.Content>
            <Combobox.List maxHeight="500px" overflowY="auto">
              {collection.items.map((item) => (
                <Combobox.Item key={item.value} item={item} gap="4">
                  <styled.img
                    src={getAlbumArtPublicPath(Number(item.value))}
                    alt={`${item.label} album art`}
                    objectFit="contain"
                    w="auto"
                    h="full"
                  />
                  <HStack justifyContent="space-between" w="full">
                    <Combobox.ItemText>{item.label}</Combobox.ItemText>
                    <Combobox.ItemIndicator>✓</Combobox.ItemIndicator>
                  </HStack>
                </Combobox.Item>
              ))}
            </Combobox.List>
          </Combobox.Content>
        </Combobox.Positioner>
      </Combobox.Root>

      {selectedSong && (
        <Card.Root mt={4}>
          <Card.Header>
            <HStack>
              <styled.img
                src={getAlbumArtPublicPath(selectedSong.id)}
                alt={`${selectedSong.title} album art`}
                objectFit="contain"
                w="24"
                h="24"
              />
              <div>
                <Card.Title>{selectedSong.title}</Card.Title>
                <Card.Description>{selectedSong.description}</Card.Description>
              </div>
            </HStack>
          </Card.Header>
          <Card.Body>
            <Text>
              {t('song_table.length')}: {Math.floor(selectedSong.duration / 1000)}s
            </Text>
            <Text>
              {t('calculator_page.normal_difficulty')}: {selectedSong.difficulty.normal} (Combo:{' '}
              {selectedSong.maxCombo.normal}) - {t('calculator_page.ap_label')}:{' '}
              {calculateAP(selectedSong.maxCombo.normal)}
            </Text>
            <Text>
              {t('calculator_page.hard_difficulty')}: {selectedSong.difficulty.hard} (Combo:{' '}
              {selectedSong.maxCombo.hard}) - {t('calculator_page.ap_label')}:{' '}
              {calculateAP(selectedSong.maxCombo.hard)}
            </Text>
            <Text>
              {t('calculator_page.expert_difficulty')}: {selectedSong.difficulty.expert} (Combo:{' '}
              {selectedSong.maxCombo.expert}) - {t('calculator_page.ap_label')}:{' '}
              {calculateAP(selectedSong.maxCombo.expert)}
            </Text>
            <Text>
              {t('calculator_page.master_difficulty')}: {selectedSong.difficulty.master} (Combo:{' '}
              {selectedSong.maxCombo.master}) - {t('calculator_page.ap_label')}:{' '}
              {calculateAP(selectedSong.maxCombo.master)}
            </Text>
          </Card.Body>
        </Card.Root>
      )}
    </>
  );
}
